func worker(ctx context.Context, in <-chan int) <-chan int {
    out := make(chan int)
    go func() {
        defer close(out)
        for n := range in {
            select {
            case <-ctx.Done():
                return // Hủy an toàn
            case out <- n * 2:
            }
        }
    }()
    return out
}

